"""Live line cards and a user-initiated, bounded Web Audio player."""
import html
from theme import dark_css

LIVE_CSS=r'''.live-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.live-heading p{max-width:760px}.live-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.live-line{padding:20px;border:1px solid var(--line);border-radius:12px;background:#fff;min-width:0}.live-line.is-listening{border-color:var(--blue);box-shadow:0 0 0 1px var(--blue)}.live-line-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.live-line h3{font-size:16px;margin:0}.live-state{border-radius:20px;padding:3px 10px;background:#f1f4f8;font-size:12px;color:#63738c;white-space:nowrap}.live-line.is-active .live-state{background:#e9f7f1;color:#157855}.live-line dl{margin:20px 0}.live-line dl>div{display:flex;justify-content:space-between;gap:12px;margin:9px 0}.live-line dt{color:var(--muted);font-size:12px}.live-line dd{margin:0;overflow-wrap:anywhere;text-align:right}.live-card-bottom{display:flex;flex-direction:column;align-items:stretch;gap:16px}.live-card-bottom small{min-height:20px;font-size:11px}.live-card-bottom button{width:100%;height:40px;min-height:40px;padding:8px 12px}.live-toolbar{display:flex;align-items:center;gap:16px;flex-wrap:wrap}.live-toolbar label{display:flex;align-items:center;gap:10px;margin:0}.live-toolbar input{width:130px}.live-stop{height:40px;min-height:40px;margin-left:auto}.live-player-title{display:flex;align-items:center;gap:10px}.live-player-title h2{margin:0}.live-pulse{width:9px;height:9px;flex:none;border-radius:50%;background:#b5c0cf}.live-pulse.on{background:#16a273;box-shadow:0 0 0 4px #16a27318}.live-note{font-size:12px;margin:14px 0 0}.live-preview-badge{font-size:11px;color:#6c7e98;background:#f1f5fc;border:1px solid #e0e8f5;border-radius:20px;padding:4px 10px;white-space:nowrap}.live-error:empty{display:none}
.has-live-monitor #live-player{position:fixed;z-index:25;left:calc(var(--nav-width) + 38px);right:38px;bottom:18px;max-width:1460px;margin-inline:auto;box-shadow:0 8px 40px #20375e20;border-color:#ccdcf5}.has-live-monitor #live-player .live-note{display:none}.has-live-monitor .workspace-main{padding-bottom:230px}
@media(max-width:1200px) and (min-width:861px){.has-live-monitor #live-player{left:calc(var(--nav-width) + 26px);right:26px}}
@media(max-width:860px){.has-live-monitor #live-player{left:22px;right:22px}}
@media(max-width:540px){.has-live-monitor #live-player{left:14px;right:14px;bottom:calc(14px + env(safe-area-inset-bottom,0px))}}
@media(min-width:1600px){.live-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.live-line{padding:18px}.live-line-heading{align-items:flex-start;flex-wrap:wrap}.live-line dl>div{gap:6px}}
@media(max-width:600px){.live-grid{grid-template-columns:1fr}.live-heading{flex-wrap:wrap}.live-toolbar{gap:12px}.live-stop{margin-left:0;width:100%}}'''

def render_live(csrf):
    nonce=html.escape(csrf,quote=True)
    cards=''.join('<article class="live-line" data-line="'+str(n)+'"><div class="live-line-heading"><h3>線路 '+str(n)+'</h3><span class="live-state">等待讀取</span></div><dl><div><dt>電話</dt><dd class="live-phone">—</dd></div><div><dt>線路電壓</dt><dd class="live-voltage">—</dd></div></dl><div class="live-card-bottom"><small class="live-updated">等待設備資料</small><button type="button" data-listen="'+str(n)+'">監聽此線路</button></div></article>' for n in range(1,5))
    return '<style>'+LIVE_CSS+dark_css(LIVE_CSS)+'''</style><section><div class="live-heading"><div><h2>即時線路狀態</h2><p class="muted">選擇線路開始聆聽。電話仍由現場話機操作，聲音經由 NAS 傳送到目前的瀏覽器。</p></div><span class="live-preview-badge">即時音訊</span></div><p id="live-status-note" class="muted" role="status">正在讀取設備狀態…</p><div class="live-grid">'''+cards+'''</div></section><section id="live-player"><div class="section-heading"><div class="live-player-title"><span id="live-pulse" class="live-pulse"></span><h2 id="live-title">尚未開始監聽</h2></div></div><p id="live-message" role="status" aria-live="polite">按下線路上的「監聽此線路」後播放。</p><p id="live-error" class="error live-error" role="alert"></p><div class="live-toolbar"><label for="live-volume">音量 <input id="live-volume" type="range" min="0" max="1" step="0.05" value="0.8"></label><button type="button" id="live-stop" class="secondary live-stop" disabled>停止監聽</button></div><p class="muted live-note">音訊只在記憶體中短暫緩衝，不另存監聽音檔。關閉頁面或連線逾時會自動停止；同時使用者共用同一條監聽線路。</p><p class="muted live-note">設備無法提供音訊或格式不符時會顯示原因；音訊連線中斷後請重新開始監聽。</p></section><script>
(()=>{'use strict';const csrf="'''+nonce+'''",cards=[...document.querySelectorAll('.live-line')],buttons=[...document.querySelectorAll('[data-listen]')],stopButton=document.getElementById('live-stop'),message=document.getElementById('live-message'),error=document.getElementById('live-error'),title=document.getElementById('live-title'),pulse=document.getElementById('live-pulse'),volume=document.getElementById('live-volume');let token=null,line=null,sequence=0,generation=0,context=null,gain=null,nextTime=0,sources=new Set(),starting=false,online=false,audioSeen=false,leaving=false;
function buttonState(){document.body.classList.toggle('has-live-monitor',starting||!!token);buttons.forEach(b=>{const selected=line===Number(b.dataset.listen);b.disabled=starting||!!token||!online;b.textContent=selected&&token?'正在監聽':'監聽此線路';b.closest('.live-line').classList.toggle('is-listening',selected&&!!token)});stopButton.disabled=!token&&!starting}
async function post(path,data){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({csrf,...data}),cache:'no-store'});let value;try{value=await r.json()}catch(e){throw Error('操作未完成，請重新整理頁面後再試')}if(!r.ok)throw Error(value.error||'操作未完成');return value}
function clearAudio(){for(const s of sources){try{s.stop()}catch(e){}}sources.clear();nextTime=0}
async function stop(notify=true){++generation;const old=token;token=null;line=null;starting=false;clearAudio();pulse.classList.remove('on');title.textContent='尚未開始監聽';message.textContent='監聽已停止。';buttonState();if(old&&notify){try{await post('/live/stop',{token:old})}catch(e){error.textContent='停止要求未送達；監聽會在連線逾時後自動停止。'}}}
function schedule(encoded){const raw=atob(encoded);if(raw.length%2)throw Error('音訊資料不完整');const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0)),view=new DataView(bytes.buffer),buffer=context.createBuffer(1,bytes.length/2,8000),samples=buffer.getChannelData(0);for(let i=0;i<samples.length;i++)samples[i]=view.getInt16(i*2,true)/32768;const now=context.currentTime;if(nextTime>now+1.3)clearAudio();nextTime=Math.max(nextTime,now+.08);const source=context.createBufferSource();source.buffer=buffer;source.connect(gain);sources.add(source);source.onended=()=>{sources.delete(source);source.disconnect()};source.start(nextTime);nextTime+=buffer.duration;if(!audioSeen){audioSeen=true;message.textContent='正在播放線路 '+line+' 的即時聲音。';pulse.classList.add('on')}}
async function pollAudio(myGeneration){while(token&&generation===myGeneration){const current=token;try{const r=await fetch('/api/live/audio?'+new URLSearchParams({token:current,after:sequence}),{cache:'no-store'}),data=await r.json();if(generation!==myGeneration)return;if(!r.ok)throw Error(data.error||'音訊連線中斷');for(const chunk of data.chunks){schedule(chunk.pcm);sequence=chunk.sequence}if(!data.chunks.length){if(!audioSeen)message.textContent='監聽已啟動，等待線路音訊…';await new Promise(resolve=>setTimeout(resolve,150))}}catch(e){if(generation!==myGeneration)return;await stop();error.textContent=e.message;return}}}
buttons.forEach(b=>b.addEventListener('click',async()=>{if(starting||token)return;starting=true;const myGeneration=++generation;line=Number(b.dataset.listen);error.textContent='';audioSeen=false;buttonState();title.textContent='正在連接線路 '+line;message.textContent='準備監聽音訊…';try{const Audio=context||new (window.AudioContext||window.webkitAudioContext)();context=Audio;if(!gain){gain=context.createGain();gain.connect(context.destination)}gain.gain.value=Number(volume.value);await context.resume();const result=await post('/live/start',{line});if(myGeneration!==generation||leaving){await post('/live/stop',{token:result.token});return}token=result.token;sequence=result.sequence;starting=false;title.textContent='監聽線路 '+line;message.textContent='監聽已啟動，等待線路音訊…';buttonState();pollAudio(myGeneration)}catch(e){if(myGeneration!==generation)return;await stop();error.textContent=e.message}}));stopButton.addEventListener('click',()=>stop());volume.addEventListener('input',()=>{if(gain)gain.gain.value=Number(volume.value)});
async function refresh(){if(leaving)return;try{const r=await fetch('/api/live/status',{cache:'no-store'});if(!r.ok)throw Error('狀態讀取失敗');const data=await r.json(),live=data.live;online=data.connection.status==='online';document.getElementById('live-status-note').textContent=!online?'答錄機暫時無法連線，等待恢復。':live.status_stale?'設備狀態尚未更新，顯示上次收到的資料。':live.lines.every(x=>!x.updated)?'等待設備回傳線路狀態…':'每 5 秒更新線路狀態。';for(const row of live.lines){const card=cards[row.line-1];card.querySelector('.live-state').textContent=row.stale&&row.updated?'狀態待更新':row.status;card.classList.toggle('is-active',online&&!row.stale&&[4,5,6,7,8,9,10,12].includes(row.state));card.querySelector('.live-phone').textContent=row.phone||'—';card.querySelector('.live-voltage').textContent=row.voltage===null||row.stale?'—':row.voltage+' V';card.querySelector('.live-updated').textContent=row.updated?'更新 '+row.updated.replace('T',' '):'等待設備資料'}buttonState()}catch(e){online=false;document.getElementById('live-status-note').textContent='無法連到管理台，正在重試…';buttonState()}}
window.addEventListener('pagehide',()=>{leaving=true;++generation;clearAudio();if(token)navigator.sendBeacon('/live/stop',new URLSearchParams({csrf,token}));token=null;if(context)context.close()});refresh();setInterval(refresh,3000);buttonState();})();
</script>'''
